// =============================================================================
// FP32 Twiddle Factor ROM -- synthesizable case-statement version
// =============================================================================
// AUTO-GENERATED by generate_fp32_twiddles.py -- do not hand-edit the ROM
// table below; re-run the generator instead.
//
// Mirrors twiddle_factor_unified in verilog_sources/twiddle_rom_synthesizable.v:
// same dynamic k-scaling for runtime N, same half-plane symmetry +
// conjugation, same hardcoded -1.0 midpoint. The stored word is 64-bit
// complex FP32 instead of the 24-bit unified FP8+FP4 word, and there is no
// PRECISION port.
//
// ROM word format: [63:32] FP32 Real, [31:0] FP32 Imag
//
// FIX (synthesis): replaced the $readmemb-based memory with a fully
// synthesizable registered-case ROM. All 512 entries are sourced
// directly from twiddles_fp32_1024.txt (authoritative) via
// generate_fp32_twiddles.py. Yosys/OpenROAD infer this as a ROM mapped to
// library cells -- no external file dependency at synthesis time, no
// working-directory-relative path to get wrong.
//
// Conjugate symmetry: only k=0..511 are stored.
//   W_N^{N-k} = conj(W_N^k) -> second half handled by flipping the
//   imaginary sign bit. k=512 (W=-1+0j) is hardcoded separately.
//
// Internally 1-cycle pipelined at the address/lookup boundary (register
// between "2. Symmetry Logic" and "3. ROM"): a single flat 512-way
// case statement measured (on the FP16 baseline's identical structure, on a
// real post-route netlist) as a ~40-gate-deep combinational chain (not the
// balanced ~log2(512)-level tree a well-structured mux would give
// -- Yosys/ABC do not automatically balance one huge flat case with fully
// arbitrary constants and no sharing opportunity). The lookup below is
// therefore written as an explicit 16-way outer selection over
// 16 independent 32-way inner blocks
// (rom_addr[8:5] picks the block,
// rom_addr[4:0] picks within it), still fully combinational
// and still inside the same single post-register cycle -- this just gives
// the synthesis tool a hierarchy to map onto instead of one flat
// 512-way structure, bounding each stage's depth to a
// 32-way / 16-way mux. The caller must add 1
// matching cycle to its alignment pipeline for the address/lookup register
// -- see TWIDDLE_LATENCY in fp32_template_generator.py.
// =============================================================================

module twiddle_factor_fp32 #(
    parameter MAX_N      = 1024,
    parameter ADDR_WIDTH = $clog2(MAX_N) + 1
)(
    input                    clk,
    input  [ADDR_WIDTH-1:0] k,            // Index k
    input  [ADDR_WIDTH-1:0] n,            // Current FFT size N
    output reg [63:0]       twiddle_out
);

    // --------------------------------------------------------
    // 1. Dynamic Scaling Logic
    // --------------------------------------------------------
    reg [ADDR_WIDTH-1:0] scaled_k;

    always @(*) begin
        case (n)
            1024: scaled_k = k;
            512:  scaled_k = {k, 1'b0};         // k * 2
            256:  scaled_k = {k, 2'b00};        // k * 4
            128:  scaled_k = {k, 3'b000};       // k * 8
            64:   scaled_k = {k, 4'b0000};      // k * 16
            32:   scaled_k = {k, 5'b00000};     // k * 32
            16:   scaled_k = {k, 6'b000000};    // k * 64
            8:    scaled_k = {k, 7'b0000000};   // k * 128
            4:    scaled_k = {k, 8'b00000000};  // k * 256
            2:    scaled_k = {k, 9'b000000000}; // k * 512
            default: scaled_k = 11'd0;
        endcase
    end

    // --------------------------------------------------------
    // 2. Symmetry Logic
    // --------------------------------------------------------
    reg        use_conjugate_w;
    reg [9:0]  rom_addr_w;       // Address within the 0-511 block
    reg        is_midpoint_w;

