    reg [9:0]  rom_addr;
    reg        is_midpoint;

    always @(posedge clk) begin
        use_conjugate <= use_conjugate_w;
        rom_addr      <= rom_addr_w;
        is_midpoint   <= is_midpoint_w;
    end

