            5'd18: block_data[15] = 64'hBF7F0E58BDAFB680;
            5'd19: block_data[15] = 64'hBF7F2F9DBDA3308C;
            5'd20: block_data[15] = 64'hBF7F4E6DBD96A905;
            5'd21: block_data[15] = 64'hBF7F6AC7BD8A200A;
            5'd22: block_data[15] = 64'hBF7F84ABBD7B2B74;
            5'd23: block_data[15] = 64'hBF7F9C18BD621469;
            5'd24: block_data[15] = 64'hBF7FB10FBD48FB30;
            5'd25: block_data[15] = 64'hBF7FC38FBD2FE007;
            5'd26: block_data[15] = 64'hBF7FD397BD16C32C;
            5'd27: block_data[15] = 64'hBF7FE129BCFB49BA;
            5'd28: block_data[15] = 64'hBF7FEC43BCC90AB0;
            5'd29: block_data[15] = 64'hBF7FF4E6BC96C9B6;
            5'd30: block_data[15] = 64'hBF7FFB11BC490E90;
            5'd31: block_data[15] = 64'hBF7FFEC4BBC90F88;
            default: block_data[15] = 64'h0000000000000000;
        endcase
    end

    reg [63:0] raw_data;

    always @(*) begin
        raw_data = block_data[rom_addr[8:5]];
    end

    // --------------------------------------------------------
    // 4. Output Generation
    // --------------------------------------------------------
    always @(*) begin
        if (is_midpoint) begin
            // Hardcoded -1.0 (real = -1.0 -> 0xBF800000, imag = +0.0 -> 0x00000000)
            twiddle_out = 64'hBF80_0000_0000_0000;
        end else begin
            twiddle_out = raw_data;

            // Apply conjugate (flip the sign of the imaginary part)
            if (use_conjugate) begin
                if (twiddle_out[31:0] != 32'h0000_0000)
                    twiddle_out[31:0] = {~twiddle_out[31], twiddle_out[30:0]};
            end
        end
    end

endmodule
